-- 세트 349: 도커 run 옵션 드릴 실습: -w, --hostname, --env-file, -e 우선순위, --entrypoint, --add-host, --label 필터, create·start, --init·--rm
-- 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다. docs/specs/spec_docker_run_options_set.md
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (349, 1, '작업 폴더를 정해서 실행하기 (-w)', '컨테이너 **`wd`** 를 `alpine` 으로 실행하되, 컨테이너 안의 **작업 폴더를 `/srv/data`** 로 정해서 시작하세요. 시작하자마자 `pwd` 를 실행해 현재 위치를 출력하면 됩니다.', '`docker run` 에는 이미지 안에 적힌 작업 폴더를 이번 실행에서만 바꾸는 옵션이 있어요(`-w` 또는 긴 이름). 없는 폴더여도 알아서 만들어 줍니다. 실행 결과는 `docker logs 이름` 으로 볼 수 있어요.', 'docker run --name wd -w /srv/data alpine pwd
docker logs wd

# -w 는 이미지의 WORKDIR 을 이번 실행에서만 덮어쓴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.Config.WorkingDir}}'' wd)\\" = \\"/srv/data\\" ] ) && ( [ \\"$(docker logs wd 2>&1)\\" = \\"/srv/data\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "wd 컨테이너의 작업 폴더가 /srv/data 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Config.WorkingDir}}'' wd)\\" = \\"/srv/data\\" ]"]}, {"label": "pwd 출력이 /srv/data 다", "cmd": ["sh", "-c", "[ \\"$(docker logs wd 2>&1)\\" = \\"/srv/data\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 2, '컨테이너 호스트 이름 붙이기 (--hostname)', '컨테이너 **`hn`** 을 `alpine` 으로 실행하되, 컨테이너 안에서 보이는 **호스트 이름을 `etude-box`** 로 정하세요. 시작하자마자 `hostname` 명령을 실행해 그 이름을 출력하게 합니다.', '컨테이너의 기본 호스트 이름은 컨테이너 ID 앞부분이에요. `--hostname 이름` 으로 바꿀 수 있고, 컨테이너 **이름**(`--name`)과는 별개입니다. 실행 결과는 `docker logs` 로 확인해요.', 'docker run --name hn --hostname etude-box alpine hostname
docker logs hn

# --name 은 도커가 부르는 이름, --hostname 은 컨테이너 안에서 보이는 이름', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.Config.Hostname}}'' hn)\\" = \\"etude-box\\" ] ) && ( [ \\"$(docker logs hn 2>&1)\\" = \\"etude-box\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "hn 의 Hostname 이 etude-box 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.Config.Hostname}}'' hn)\\" = \\"etude-box\\" ]"]}, {"label": "hostname 출력이 etude-box 다", "cmd": ["sh", "-c", "[ \\"$(docker logs hn 2>&1)\\" = \\"etude-box\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 3, '환경 변수 파일로 한 번에 넣기 (--env-file)', '`/tmp/work/app.env` 에 `MODE=prod` 와 `REGION=ap` 가 한 줄씩 적혀 있습니다. 컨테이너 **`ef`** 를 `alpine` 으로 실행하되 이 파일의 변수를 **파일째로** 넣고, `MODE` 와 `REGION` 을 `-` 로 이어 한 줄로 출력하게 하세요(결과 `prod-ap`).', '변수를 하나씩 `-e` 로 적는 대신, `이름=값` 이 줄마다 적힌 파일을 통째로 읽는 옵션이 있어요(`--env-file 파일`). 출력은 `sh -c` 로 셸에게 `echo $MODE-$REGION` 을 시키면 되고, 따옴표로 감싸야 호스트 셸이 먼저 풀지 않아요.', 'docker run --name ef --env-file /tmp/work/app.env alpine sh -c ''echo $MODE-$REGION''
docker logs ef

# 파일의 각 줄이 -e 이름=값 하나씩과 같다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''MODE=prod\\\\nREGION=ap\\\\n'' > /tmp/work/app.env; true"]', '["sh", "-c", "( docker inspect -f ''{{json .Config.Env}}'' ef | grep -q ''MODE=prod'' ) && ( docker inspect -f ''{{json .Config.Env}}'' ef | grep -q ''REGION=ap'' ) && ( [ \\"$(docker logs ef 2>&1)\\" = \\"prod-ap\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ef 의 Env 에 MODE=prod 가 있다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Env}}'' ef | grep -q ''MODE=prod''"]}, {"label": "ef 의 Env 에 REGION=ap 가 있다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Env}}'' ef | grep -q ''REGION=ap''"]}, {"label": "출력이 prod-ap 다", "cmd": ["sh", "-c", "[ \\"$(docker logs ef 2>&1)\\" = \\"prod-ap\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 4, '-e 로 파일 값 덮어쓰기', '같은 `/tmp/work/app.env` 파일(`MODE=prod`, `REGION=ap`)을 쓰되, 컨테이너 **`ov`** 에서는 `MODE` 만 **`dev`** 로 바꿔 실행하세요. 파일은 고치지 않습니다. `MODE` 와 `REGION` 을 `-` 로 이어 출력하면 `dev-ap` 이 나와야 해요.', '같은 이름의 변수가 파일과 `-e` 양쪽에 있으면 `-e` 로 직접 적은 값이 이겨요. 파일의 나머지 변수(`REGION`)는 그대로 들어옵니다. 두 옵션을 모두 쓰면 됩니다.', 'docker run --name ov --env-file /tmp/work/app.env -e MODE=dev alpine sh -c ''echo $MODE-$REGION''
docker logs ov

# 옵션을 적는 순서와 상관없이 -e 가 이긴다. Env 목록에는 prod 도 보이지만 마지막 값(dev)이 쓰인다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; printf ''MODE=prod\\\\nREGION=ap\\\\n'' > /tmp/work/app.env; true"]', '["sh", "-c", "( [ \\"$(docker logs ov 2>&1)\\" = \\"dev-ap\\" ] ) && ( docker inspect -f ''{{range .Config.Env}}{{println .}}{{end}}'' ov | grep ''^MODE='' | tail -n 1 | grep -qx ''MODE=dev'' ) && ( grep -qx ''MODE=prod'' /tmp/work/app.env )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "출력이 dev-ap 다", "cmd": ["sh", "-c", "[ \\"$(docker logs ov 2>&1)\\" = \\"dev-ap\\" ]"]}, {"label": "Env 의 마지막 MODE 값이 dev 다", "cmd": ["sh", "-c", "docker inspect -f ''{{range .Config.Env}}{{println .}}{{end}}'' ov | grep ''^MODE='' | tail -n 1 | grep -qx ''MODE=dev''"]}, {"label": "app.env 파일은 그대로 prod 다", "cmd": ["sh", "-c", "grep -qx ''MODE=prod'' /tmp/work/app.env"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 5, 'env-file 이 두 개일 때 같은 이름의 값은', '`a.env` 에 `MODE=prod`, `b.env` 에 `MODE=stage` 가 적혀 있습니다. `docker run --env-file a.env --env-file b.env alpine env` 로 실행하면 컨테이너 안의 `MODE` 값은 무엇일까요?', '옵션은 적은 순서대로 읽히고, 같은 이름이 또 나오면 어느 쪽이 남을지 생각해 보세요. 설정을 "위에서 아래로 덮어쓰기" 하는 일반적인 방식과 같습니다.', NULL, NULL, '[]', 'choice', '["`prod` 가 된다 (먼저 적은 파일이 이긴다)", "`prod` 와 `stage` 가 둘 다 들어간다", "`stage` 가 된다 (뒤에 적은 파일이 이긴다)", "같은 이름이라 도커가 오류를 내고 멈춘다"]', 2, '파일은 적은 순서대로 읽고, 같은 이름이면 **나중에 읽은 값이 이깁니다.** 그래서 `MODE=stage` 가 됩니다. `-e` 로 직접 적은 값은 파일보다 더 우선이라, 우선순위는 `-e` > 뒤쪽 파일 > 앞쪽 파일 순이에요.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 6, '이미지의 실행 파일 바꿔 실행하기 (--entrypoint)', '컨테이너 **`ep`** 를 `alpine` 으로 실행하되, 실행 파일을 **`/bin/echo`** 로 바꾸고 인자로 `hello etude` 를 주세요. 기본 명령(`/bin/sh`)이 아니라 echo 가 직접 실행돼 `hello etude` 가 출력되어야 합니다.', '이미지 이름 **뒤**에 적는 것은 인자(명령)이고, 실행할 프로그램 자체를 바꾸는 옵션은 이미지 이름 **앞**에 적어요(`--entrypoint 프로그램`). 설정에는 `Config.Entrypoint` 로 남습니다.', 'docker run --name ep --entrypoint /bin/echo alpine hello etude
docker logs ep
docker inspect -f ''{{json .Config.Entrypoint}}'' ep

# 옵션은 이미지 이름 앞, 인자는 이미지 이름 뒤', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker inspect -f ''{{json .Config.Entrypoint}}'' ep | grep -qx ''\\\\[\\"/bin/echo\\"\\\\]''  ) && ( docker inspect -f ''{{json .Config.Cmd}}'' ep | grep -qx ''\\\\[\\"hello\\",\\"etude\\"\\\\]''  ) && ( [ \\"$(docker logs ep 2>&1)\\" = \\"hello etude\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Entrypoint 가 /bin/echo 다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Entrypoint}}'' ep | grep -qx ''\\\\[\\"/bin/echo\\"\\\\]'' "]}, {"label": "인자(Cmd)가 hello etude 다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .Config.Cmd}}'' ep | grep -qx ''\\\\[\\"hello\\",\\"etude\\"\\\\]'' "]}, {"label": "출력이 hello etude 다", "cmd": ["sh", "-c", "[ \\"$(docker logs ep 2>&1)\\" = \\"hello etude\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 7, '이름에 주소 직접 연결하기 (--add-host)', '컨테이너 **`ah`** 를 `alpine` 으로 실행하되, 컨테이너 안의 `/etc/hosts` 에 이름 **`mydb`** 가 **호스트 머신을 가리키도록** 추가하고, `grep mydb /etc/hosts` 로 그 줄을 출력하게 하세요. 주소 자리에는 숫자를 쓰는 대신 도커가 호스트 주소로 풀어 주는 예약어 `host-gateway` 를 씁니다.', '`--add-host 이름:주소` 는 컨테이너의 `/etc/hosts` 에 줄 하나를 더해요. 이름과 주소 사이는 콜론이고, 설정에는 `HostConfig.ExtraHosts` 로 남습니다. 확인은 `docker logs` 로 해요.', 'docker run --name ah --add-host mydb:host-gateway alpine grep mydb /etc/hosts
docker logs ah

# DNS 없이도 mydb 라는 이름이 통한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( docker inspect -f ''{{json .HostConfig.ExtraHosts}}'' ah | grep -q ''mydb:host-gateway'' ) && ( docker logs ah 2>&1 | grep -q mydb )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "ExtraHosts 에 mydb:host-gateway 가 있다", "cmd": ["sh", "-c", "docker inspect -f ''{{json .HostConfig.ExtraHosts}}'' ah | grep -q ''mydb:host-gateway''"]}, {"label": "출력에 mydb 줄이 있다", "cmd": ["sh", "-c", "docker logs ah 2>&1 | grep -q mydb"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 8, '라벨 붙여 띄우기 (--label)', '컨테이너 **`lb1`** 에는 라벨 `team=blue`, **`lb2`** 에는 라벨 `team=red` 를 붙여서 `alpine` 으로 `sleep 300` 을 **백그라운드**로 실행하세요. 두 컨테이너 모두 실행 중이어야 합니다.', '`--label 키=값` 은 컨테이너에 이름표를 붙여요(`-l` 로도 씁니다). 백그라운드 실행은 `-d` 이고, 설정의 `Config.Labels` 에서 값을 볼 수 있어요.', 'docker run -d --name lb1 --label team=blue alpine sleep 300
docker run -d --name lb2 --label team=red alpine sleep 300
docker inspect -f ''{{json .Config.Labels}}'' lb1 lb2

# 라벨은 이미지가 아니라 컨테이너에도 직접 붙일 수 있다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{index .Config.Labels \\"team\\"}}'' lb1)\\" = \\"blue\\" ] ) && ( [ \\"$(docker inspect -f ''{{index .Config.Labels \\"team\\"}}'' lb2)\\" = \\"red\\" ] ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' lb1)\\" = \\"true\\" ] && [ \\"$(docker inspect -f ''{{.State.Running}}'' lb2)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "lb1 의 team 라벨이 blue 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{index .Config.Labels \\"team\\"}}'' lb1)\\" = \\"blue\\" ]"]}, {"label": "lb2 의 team 라벨이 red 다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{index .Config.Labels \\"team\\"}}'' lb2)\\" = \\"red\\" ]"]}, {"label": "둘 다 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' lb1)\\" = \\"true\\" ] && [ \\"$(docker inspect -f ''{{.State.Running}}'' lb2)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 9, '라벨로 컨테이너 골라내기 (--filter label=)', '`team` 라벨이 붙은 컨테이너 세 개(`f1`, `f2`, `f3`)가 있고, 그중 하나는 이미 종료됐습니다. **`team=blue`** 라벨이 붙은 컨테이너의 이름만, **종료된 것까지 모두**, 한 줄에 하나씩 `/tmp/work/blue.txt` 에 저장하세요.', '`docker ps` 의 필터는 `--filter label=키=값` 이에요. 기본으로는 실행 중인 것만 보이니 전체를 보는 옵션을 더하고, 이름만 한 줄씩 뽑는 것은 `--format` 템플릿으로 합니다.', 'docker ps -a --filter label=team=blue --format ''{{.Names}}'' > /tmp/work/blue.txt
cat /tmp/work/blue.txt

# 필터는 라벨 키=값 전체를 적는다. -a 가 없으면 종료된 f3 이 빠진다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; docker run -d --name f1 --label team=blue alpine sleep 300 >/dev/null; docker run -d --name f2 --label team=red alpine sleep 300 >/dev/null; docker run --name f3 --label team=blue alpine true >/dev/null; true"]', '["sh", "-c", "( [ \\"$(sort /tmp/work/blue.txt 2>/dev/null | tr ''\\\\n'' '' '')\\" = \\"f1 f3 \\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "blue.txt 에 f1 과 f3 만 있다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/work/blue.txt 2>/dev/null | tr ''\\\\n'' '' '')\\" = \\"f1 f3 \\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 10, '만들어 두고 나중에 시작하기', '컨테이너를 **만들기만 하고 시작은 나중에** 하려고 합니다. `docker create` 로 만든 `c1` 을 시작하면서 그 출력까지 터미널에 이어 붙여 보는 명령의 빈칸을 채우세요.', '`docker create` 는 컨테이너만 만들어 두고 실행하지 않아요(상태 `created`). 이미 만들어진 컨테이너를 켜는 명령이 빈칸이고, `-a` 는 그 출력에 연결하는 옵션입니다.', NULL, NULL, '[]', 'fill', '["start", "run", "exec", "attach"]', NULL, '`docker create` 는 만들기만 하고 `docker start` 가 켭니다. `-a` 를 붙이면 출력에 연결돼 `hi` 가 바로 보여요. `run` 은 create 와 start 를 한 번에 하는 명령이라 이미 만든 `c1` 에는 쓸 수 없고, `exec` 는 **실행 중인** 컨테이너에, `attach` 는 이미 도는 컨테이너에 붙는 명령입니다.', '[0]', 'docker create --name c1 alpine echo hi && docker {0} -a c1', NULL, '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 11, '--init 과 --rm 으로 깔끔하게 돌리기', '컨테이너 **`tmpc`** 를 `alpine` 으로 `sleep 300` 을 **백그라운드**로 실행하되, 좀비 프로세스를 거둬 주는 작은 초기화 프로세스를 **1번 프로세스로 넣고**(`--init`), **멈추면 컨테이너가 자동으로 지워지게**(`--rm`) 하세요.', '두 옵션 모두 값이 없는 스위치예요. 설정에서는 `HostConfig.Init` 과 `HostConfig.AutoRemove` 로 켜져 있는지 볼 수 있습니다.', 'docker run -d --init --rm --name tmpc alpine sleep 300
docker inspect -f ''{{.HostConfig.Init}} {{.HostConfig.AutoRemove}}'' tmpc

# 멈추면 (docker stop tmpc) 컨테이너가 알아서 사라진다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker rmi -f $(docker images -aq) >/dev/null 2>&1; rm -rf /tmp/work; mkdir -p /tmp/work; docker pull -q alpine >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{.HostConfig.Init}}'' tmpc)\\" = \\"true\\" ] ) && ( [ \\"$(docker inspect -f ''{{.HostConfig.AutoRemove}}'' tmpc)\\" = \\"true\\" ] ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' tmpc)\\" = \\"true\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Init 이 켜져 있다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.Init}}'' tmpc)\\" = \\"true\\" ]"]}, {"label": "AutoRemove 가 켜져 있다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.HostConfig.AutoRemove}}'' tmpc)\\" = \\"true\\" ]"]}, {"label": "실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' tmpc)\\" = \\"true\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]'),
  (349, 12, '옵션을 주어 띄우고 확인하는 흐름', '`/tmp/work/app.env` 를 만들어 컨테이너 하나를 옵션과 함께 띄우고 결과를 확인한 뒤 정리하는 흐름을 앞에서 뒤로 놓으세요.', '먼저 재료(파일)를 만들고, 그다음 옵션을 붙여 실행하고, 값을 확인하고, 마지막에 치웁니다. 확인은 설정 쪽 → 출력 쪽 순서로 해 보세요.', NULL, NULL, '[]', 'order', '["`app.env` 파일에 `이름=값` 을 줄마다 적는다", "`docker run -d --name app --env-file app.env --label team=blue alpine sleep 300` 으로 띄운다", "`docker ps --filter label=team=blue` 로 라벨로 찾아본다", "`docker inspect -f ''{{json .Config.Env}}'' app` 으로 들어간 변수를 확인한다", "`docker exec app env` 로 컨테이너 안에서도 보이는지 확인한다", "`docker rm -f app` 으로 정리한다"]', NULL, '**파일 작성 → run(--env-file, --label) → ps 필터 → inspect 로 설정 확인 → exec 로 안쪽 확인 → rm -f 정리** 순서입니다. 옵션은 `run` 때 한 번에 주고, 이후에는 설정(`inspect`)과 실제 동작(`exec`)을 나눠 확인하면 원인을 찾기 쉬워요.', '[0, 1, 2, 3, 4, 5]', NULL, NULL, '[{"title": "Docker 공식 문서: docker container run", "url": "https://docs.docker.com/reference/cli/docker/container/run/"}, {"title": "Docker 공식 문서: docker run 레퍼런스 (컨테이너 실행)", "url": "https://docs.docker.com/engine/containers/run/"}, {"title": "Docker 공식 문서: docker container create", "url": "https://docs.docker.com/reference/cli/docker/container/create/"}, {"title": "Docker 공식 문서: docker container start", "url": "https://docs.docker.com/reference/cli/docker/container/start/"}, {"title": "Docker 공식 문서: docker container ls (필터)", "url": "https://docs.docker.com/reference/cli/docker/container/ls/"}, {"title": "Docker 공식 문서: docker container inspect", "url": "https://docs.docker.com/reference/cli/docker/container/inspect/"}]');
